-- Gallery is isolated from SBC data and XP; submissions always require review.
create table public.gallery_set_rules (
 id integer primary key, required_cards integer not null check(required_cards between 1 and 50),
 eligible_ids integer[] not null, thresholds jsonb not null, checked_at timestamptz not null
);
alter table public.gallery_set_rules enable row level security;
grant select on public.gallery_set_rules to anon, authenticated;
create policy gallery_rules_read on public.gallery_set_rules for select to anon,authenticated using(true);
create table public.gallery_solutions (
 id uuid primary key default gen_random_uuid(), set_id integer not null references public.gallery_set_rules(id),
 user_id uuid not null default auth.uid() references public.profiles(id),
 title text not null check(length(btrim(title)) between 1 and 100), note text not null check(length(btrim(note)) between 1 and 2000),
 item_ids integer[] not null, first_owner_ids integer[] not null default '{}',
 claimed_grade text not null check(claimed_grade in ('D','C','B','A','S')),
 game_score integer not null check(game_score between 0 and 1000000000),
 proof_paths text[] not null check(cardinality(proof_paths) between 1 and 3),
 status text not null default 'pending' check(status in ('pending','approved','rejected')),
 reviewed_by uuid references public.profiles(id), reviewed_at timestamptz, created_at timestamptz not null default now()
);
alter table public.gallery_solutions enable row level security;
grant select on public.gallery_solutions to anon,authenticated;
grant insert on public.gallery_solutions to authenticated;
revoke update,delete on public.gallery_solutions from anon,authenticated;
create index gallery_solutions_set_status on public.gallery_solutions(set_id,status,created_at desc);
create index gallery_solutions_author on public.gallery_solutions(user_id,created_at desc);
create index gallery_solutions_review on public.gallery_solutions(created_at desc) where status='pending';
create policy gallery_solutions_read on public.gallery_solutions for select to anon,authenticated using (
 status='approved' or user_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.is_admin)
);
create policy gallery_solutions_insert on public.gallery_solutions for insert to authenticated with check (
 user_id=(select auth.uid()) and status='pending' and reviewed_by is null and reviewed_at is null
 and exists(select 1 from public.profiles p where p.id=(select auth.uid()))
 and not coalesce(((select auth.jwt())->>'is_anonymous')::boolean,false)
);
create or replace function fc27_private.gallery_pending_submission()
returns trigger language plpgsql set search_path='' as $$
declare r public.gallery_set_rules; p text;
begin
 new.status:='pending'; new.reviewed_by:=null; new.reviewed_at:=null; new.created_at:=now();
 select * into strict r from public.gallery_set_rules where id=new.set_id;
 if cardinality(new.item_ids)<>r.required_cards
  or cardinality(new.item_ids)<>(select count(distinct x) from unnest(new.item_ids) x)
  or not new.item_ids<@r.eligible_ids
  or not new.first_owner_ids<@new.item_ids
  or array_position(new.item_ids,null) is not null
  or array_position(new.first_owner_ids,null) is not null
  or new.game_score<(r.thresholds->>new.claimed_grade)::integer
 then raise exception 'Gallery requirements not met'; end if;
 foreach p in array new.proof_paths loop
  if p is null or split_part(p,'/',1)<>new.user_id::text or p like '%..%' then raise exception 'Invalid proof path'; end if;
 end loop;
 if (select count(*) from public.gallery_solutions where user_id=new.user_id and created_at>now()-interval '1 day')>=10 then raise exception 'Daily submission limit reached'; end if;
 return new;
end;
$$;
revoke all on function fc27_private.gallery_pending_submission() from public,anon,authenticated;
create trigger gallery_pending_submission before insert on public.gallery_solutions for each row execute function fc27_private.gallery_pending_submission();
create or replace function fc27_private.moderate_gallery_solution(p_id uuid,p_status text)
returns void language plpgsql security definer set search_path='' as $$
declare v_admin uuid:=public.assert_admin(); v_solution public.gallery_solutions; p text;
begin
 if p_status is null or p_status not in ('approved','rejected') then raise exception 'Invalid status'; end if;
 select * into strict v_solution from public.gallery_solutions where id=p_id for update;
 if p_status='approved' then
  foreach p in array v_solution.proof_paths loop
   if not exists(select 1 from storage.objects where bucket_id='gallery-proofs' and name=p and split_part(name,'/',1)=v_solution.user_id::text) then raise exception 'Proof missing'; end if;
  end loop;
 end if;
 update public.gallery_solutions set status=p_status,reviewed_by=v_admin,reviewed_at=now() where id=p_id;
end;
$$;
revoke all on function fc27_private.moderate_gallery_solution(uuid,text) from public,anon;
grant execute on function fc27_private.moderate_gallery_solution(uuid,text) to authenticated;
create or replace function public.moderate_gallery_solution(p_id uuid,p_status text)
returns void language sql security invoker set search_path='' as $$ select fc27_private.moderate_gallery_solution(p_id,p_status); $$;
revoke all on function public.moderate_gallery_solution(uuid,text) from public,anon;
grant execute on function public.moderate_gallery_solution(uuid,text) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
 values('gallery-proofs','gallery-proofs',false,10485760,array['image/jpeg','image/png','image/webp']);
create policy gallery_proofs_insert on storage.objects for insert to authenticated with check (
 bucket_id='gallery-proofs' and (storage.foldername(name))[1]=(select auth.uid())::text
 and exists(select 1 from public.profiles p where p.id=(select auth.uid()))
 and not coalesce(((select auth.jwt())->>'is_anonymous')::boolean,false)
);
create policy gallery_proofs_select on storage.objects for select to anon,authenticated using (
 bucket_id='gallery-proofs' and (
 (storage.foldername(name))[1]=(select auth.uid())::text
 or exists(select 1 from public.gallery_solutions s where s.status='approved' and storage.objects.name=any(s.proof_paths))
 or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.is_admin))
);
create policy gallery_proofs_delete on storage.objects for delete to authenticated using (
 bucket_id='gallery-proofs' and (storage.foldername(name))[1]=(select auth.uid())::text
 and not exists(select 1 from public.gallery_solutions s where storage.objects.name=any(s.proof_paths))
);

